110:/** Persist reusable facts before applying filesystem metadata. Retries reuse source keys. */
111:export async function saveSqlFacts(cwd: string, attempt: SaveAttempt, facts: SaveFact[], query?: SqlQuery, onActivity?: SqlMemoryActivitySink): Promise<string[]> {
112:  if (query) return saveFactsWithQuery(cwd, attempt, facts, guardedQuery(query));
113:  const url = process.env.SQL_MEMORY_URL;
114:  if (!url) throw new Error("SQL_MEMORY_URL is not set");
115:  const pool = createLazyPool(url)();
116:  const saveQuery: SqlQuery = (sql, values) => sqlMemoryRows(pool, sql, values, "save", onActivity);
117:  saveQuery.transaction = (work) => sqlMemorySaveTransaction(pool, work, onActivity);
118:  try {
119:    return await saveFactsWithQuery(cwd, attempt, facts, saveQuery);
120:  } finally {
121:    await pool.end();
122:  }
123:}
