125:function guardedQuery(query: SqlQuery): SqlQuery {
126:  const guarded: SqlQuery = (sql, values) => {
127:    const gate = checkSqlForRole(sql, "save");
128:    if (!gate.allowed) throw new Error(`SQL save policy denied statement: ${gate.reason}`);
129:    return query(sql, values);
130:  };
131:  if (query.transaction) guarded.transaction = (work) => query.transaction!((inside) => work(guardedQuery(inside)));
132:  return guarded;
133:}
