135:async function saveFactsWithQuery(cwd: string, attempt: SaveAttempt, facts: SaveFact[], query: SqlQuery): Promise<string[]> {
136:  if (facts.length === 0) return saveNoFacts(cwd, attempt, query);
137:  const email = git(cwd, "config", "user.email");
138:  if (!email) throw new Error("SQL save requires git user.email");
139:  const branch = git(cwd, "branch", "--show-current");
140:  const sha = git(cwd, "rev-parse", "HEAD");
141:  const provenance = branch && sha ? [branch, sha] : [null, null];
142:  await query("INSERT INTO users (email) VALUES ($1) ON CONFLICT (email) DO NOTHING", [email]);
143:  await query(
144:    "INSERT INTO projects (origin_url, name) VALUES ($1, $2) ON CONFLICT (origin_url) DO NOTHING",
145:    [attempt.project, attempt.subject],
146:  );
147:  const projectRows = await query("SELECT id FROM projects WHERE origin_url = $1", [attempt.project]);
148:  const projectId = projectRows[0]?.id;
149:  if (typeof projectId !== "string") throw new Error("SQL save could not resolve project id");
150:  const ids: string[] = [];
151:  for (const [index, fact] of facts.entries()) {
152:    ids.push(await storeCorrectedFact(attempt, query, { email, projectId, provenance }, fact, index + 1));
153:  }
154:  for (const id of ids) {
155:    const rows = await query(READBACK_SQL, [attempt.project, id]);
156:    if (rows.length !== 1) throw new Error(`SQL save row was not readable for this project: ${id}`);
157:  }
158:  writeReceipt(cwd, attempt, { kind: "rows", ids });
159:  return ids;
160:}
